def run_weekly_overdue_invoice_reminders() -> dict[str, object]:
    """Return success only after one strictly validated week has all reminders and one digest confirmed, otherwise attempt exactly one HOLD notification and return a detailed hold result."""
    import json
    import logging

    log = logging.getLogger(__name__)

    def success_response(response):
        status = response.get("status")
        return isinstance(status, int) and not isinstance(status, bool) and 200 <= status < 300

    def response_failure(method, path, response):
        return f"{method} {path} returned HTTP {response.get('status')} {response.get('reason', '')}".strip()

    def notify_hold(description, phase, week=None, confirmed_ids=None):
        message = f"HOLD: {description}"
        log.error("SOFT_FAIL owner_hold phase=%s reason=%s", phase, description)
        notice = {"attempted": True, "confirmed": False}
        try:
            response = send_weekly_invoice_api_post("/owner/notify", {"message": message})
            notice.update({"status": response.get("status"), "reason": response.get("reason")})
            notice["confirmed"] = success_response(response)
            if notice["confirmed"]:
                log.info("PHASE owner_hold_confirmed phase=%s", phase)
            else:
                log.error("SOFT_FAIL owner_hold_not_confirmed phase=%s status=%s", phase, response.get("status"))
        except Exception as exc:
            notice["error"] = f"{type(exc).__name__}: {exc}"
            log.exception("SOFT_FAIL owner_hold_uncertain phase=%s", phase)
        return {
            "outcome": "hold",
            "phase": phase,
            "week": week,
            "confirmed_reminder_ids": list(confirmed_ids or []),
            "hold_reason": description,
            "owner_notification": notice,
        }

    log.info("PHASE read_last_report")
    try:
        last_response = weekly_invoice_api_request("GET", "/reports/last")
    except Exception as exc:
        return notify_hold(f"GET /reports/last had an uncertain outcome due to {type(exc).__name__}: {exc}", "last_report_read")
    if not success_response(last_response):
        return notify_hold(response_failure("GET", "/reports/last", last_response), "last_report_read")

    try:
        preliminary = prepare_weekly_invoice_batch(last_response["body_b64"], "W10=")
        week = preliminary["week"]
    except Exception as exc:
        return notify_hold(str(exc), "last_report_validation")

    invoice_path = f"/invoices?week={week}"
    log.info("PHASE read_invoices week=%s", week)
    try:
        invoices_response = weekly_invoice_api_request("GET", invoice_path)
    except Exception as exc:
        return notify_hold(f"GET {invoice_path} had an uncertain outcome due to {type(exc).__name__}: {exc}", "invoice_read", week)
    if not success_response(invoices_response):
        return notify_hold(response_failure("GET", invoice_path, invoices_response), "invoice_read", week)

    try:
        batch = prepare_weekly_invoice_batch(last_response["body_b64"], invoices_response["body_b64"])
    except Exception as exc:
        return notify_hold(str(exc), "invoice_validation", week)

    confirmed_ids = []
    for reminder in batch["reminders"]:
        invoice_id = reminder["invoice_id"]
        log.info("PHASE send_reminder invoice_id=%r", invoice_id)
        try:
            response = send_weekly_invoice_api_post("/remind", reminder)
        except Exception as exc:
            description = (
                f"reminder for invoice {invoice_id!r} had an uncertain outcome due to {type(exc).__name__}: {exc}; "
                f"already confirmed reminders ({len(confirmed_ids)}): {json.dumps(confirmed_ids, ensure_ascii=False, separators=(',', ':'))}"
            )
            return notify_hold(description, "reminder_delivery", week, confirmed_ids)
        if not success_response(response):
            description = (
                f"reminder for invoice {invoice_id!r} was not confirmed: {response_failure('POST', '/remind', response)}; "
                f"already confirmed reminders ({len(confirmed_ids)}): {json.dumps(confirmed_ids, ensure_ascii=False, separators=(',', ':'))}"
            )
            return notify_hold(description, "reminder_delivery", week, confirmed_ids)
        confirmed_ids.append(invoice_id)
        log.info("PHASE reminder_confirmed invoice_id=%r", invoice_id)

    digest = dict(batch["digest"])
    digest["reminders_sent"] = len(confirmed_ids)
    log.info("PHASE send_digest week=%s", week)
    try:
        report_response = send_weekly_invoice_api_post("/report", digest)
    except Exception as exc:
        description = (
            f"digest for week {week} had an uncertain outcome due to {type(exc).__name__}: {exc}; "
            f"all {len(confirmed_ids)} reminders were already confirmed sent for invoice ids "
            f"{json.dumps(confirmed_ids, ensure_ascii=False, separators=(',', ':'))}"
        )
        return notify_hold(description, "digest_delivery", week, confirmed_ids)
    if not success_response(report_response):
        description = (
            f"digest for week {week} was not confirmed: {response_failure('POST', '/report', report_response)}; "
            f"all {len(confirmed_ids)} reminders were already confirmed sent for invoice ids "
            f"{json.dumps(confirmed_ids, ensure_ascii=False, separators=(',', ':'))}"
        )
        return notify_hold(description, "digest_delivery", week, confirmed_ids)

    log.info("PHASE workflow_complete week=%s reminders=%s", week, len(confirmed_ids))
    return {
        "outcome": "success",
        "week": week,
        "invoice_count": digest["invoice_count"],
        "total_amount_cents": digest["total_amount_cents"],
        "reminders_sent": len(confirmed_ids),
        "flagged_invoice_ids": [],
        "digest_confirmed": True,
    }

