def send_weekly_invoice_api_post(path: str, payload: dict[str, object]) -> dict[str, object]:
    """Return one HTTP response envelope after sending exactly one allowed weekly-invoice POST with an exact route-specific JSON shape."""
    import logging

    log = logging.getLogger(__name__)
    if path == "/remind":
        if set(payload) != {"to", "invoice_id"}:
            raise ValueError("/remind payload must contain exactly to and invoice_id")
        if not isinstance(payload["to"], str) or payload["to"] == "":
            raise ValueError("/remind to must be a non-empty string")
        if not isinstance(payload["invoice_id"], str) or payload["invoice_id"] == "":
            raise ValueError("/remind invoice_id must be a non-empty string")
    elif path == "/report":
        expected = {"week", "invoice_count", "total_amount_cents", "reminders_sent", "flagged_invoice_ids"}
        if set(payload) != expected:
            raise ValueError("/report payload has invalid keys")
        for field in ("week", "invoice_count", "total_amount_cents", "reminders_sent"):
            value = payload[field]
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(f"/report {field} must be a non-boolean integer >= 0")
        if payload["flagged_invoice_ids"] != []:
            raise ValueError("/report flagged_invoice_ids must be an empty list")
    elif path == "/owner/notify":
        if set(payload) != {"message"}:
            raise ValueError("/owner/notify payload must contain exactly message")
        message = payload["message"]
        if not isinstance(message, str) or not message.startswith("HOLD: ") or len(message) <= 6:
            raise ValueError("/owner/notify message must be a non-empty HOLD message")
    else:
        raise ValueError("path is not an allowed weekly-invoice POST route")

    log.info("PHASE validated_invoice_post path=%s", path)
    return weekly_invoice_api_request("POST", path, payload)

