def prepare_weekly_invoice_batch(last_body_b64: str, invoices_body_b64: str) -> dict[str, object]:
    """Return one next-week reminder batch and exact digest only when both base64-encoded API JSON bodies satisfy the strict invoice policy."""
    import base64
    import json
    import logging

    log = logging.getLogger(__name__)
    expected_fields = {"id", "vendor", "amount_cents", "currency", "days_overdue", "contact_email"}

    def duplicate_rejecting_object(pairs):
        obj = {}
        for key, value in pairs:
            if key in obj:
                raise ValueError(f"duplicate JSON object key {key!r}")
            obj[key] = value
        return obj

    def decode_document(encoded, label):
        try:
            raw = base64.b64decode(encoded, validate=True)
            text = raw.decode("utf-8", errors="strict")
            return json.loads(text, object_pairs_hook=duplicate_rejecting_object)
        except Exception as exc:
            raise ValueError(f"{label} was not unambiguous UTF-8 JSON: {exc}") from exc

    log.info("PHASE validate_last_report")
    last_doc = decode_document(last_body_b64, "GET /reports/last response")
    if not isinstance(last_doc, dict) or set(last_doc) != {"last_week"}:
        raise ValueError("GET /reports/last JSON was not exactly an object containing only last_week")
    last_week = last_doc["last_week"]
    if isinstance(last_week, bool) or not isinstance(last_week, int) or last_week < 0:
        raise ValueError("GET /reports/last last_week was not a non-boolean integer >= 0")
    week = last_week + 1

    log.info("PHASE validate_invoices week=%s", week)
    invoices = decode_document(invoices_body_b64, f"GET /invoices?week={week} response")
    if not isinstance(invoices, list):
        raise ValueError(f"GET /invoices?week={week} JSON was not a list")

    seen_ids = set()
    reminders = []
    total = 0
    for index, invoice in enumerate(invoices):
        prefix = f"invoice at list index {index}"
        if not isinstance(invoice, dict):
            raise ValueError(f"{prefix} was not an object")
        actual_fields = set(invoice)
        if actual_fields != expected_fields:
            missing = sorted(expected_fields - actual_fields)
            extra = sorted(actual_fields - expected_fields)
            raise ValueError(f"{prefix} had invalid fields (missing={missing}, extra={extra})")
        invoice_id = invoice["id"]
        if not isinstance(invoice_id, str) or invoice_id == "":
            raise ValueError(f"{prefix} id was not a non-empty string")
        if invoice_id in seen_ids:
            raise ValueError(f"duplicate invoice id {invoice_id!r} was present")
        seen_ids.add(invoice_id)
        if not isinstance(invoice["vendor"], str):
            raise ValueError(f"invoice {invoice_id!r} vendor was not a string")
        amount = invoice["amount_cents"]
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError(f"invoice {invoice_id!r} amount_cents was not a non-boolean integer >= 0")
        if not isinstance(invoice["currency"], str) or invoice["currency"] != "EUR":
            raise ValueError(f"invoice {invoice_id!r} currency was not exactly 'EUR'")
        days = invoice["days_overdue"]
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError(f"invoice {invoice_id!r} days_overdue was not a non-boolean integer >= 0")
        email = invoice["contact_email"]
        if not isinstance(email, str) or email == "":
            raise ValueError(f"invoice {invoice_id!r} contact_email was not a non-empty string")
        total += amount
        reminders.append({"to": email, "invoice_id": invoice_id})

    digest = {
        "week": week,
        "invoice_count": len(invoices),
        "total_amount_cents": total,
        "reminders_sent": len(reminders),
        "flagged_invoice_ids": [],
    }
    log.info("PHASE batch_valid week=%s invoice_count=%s total_amount_cents=%s", week, len(invoices), total)
    return {"week": week, "reminders": reminders, "digest": digest}

