def weekly_invoice_api_request(method: str, path: str, payload: dict[str, object] | None = None) -> dict[str, object]:
    """Return the HTTP status, reason, and base64 response body from exactly one allowed request to the fixed local invoices API."""
    import base64
    import http.client
    import json
    import logging

    log = logging.getLogger(__name__)
    allowed_get = path == "/reports/last" or (
        path.startswith("/invoices?week=") and path[len("/invoices?week="):].isdigit()
    )
    allowed_post = path in {"/remind", "/report", "/owner/notify"}
    if (method == "GET" and not allowed_get) or (method == "POST" and not allowed_post) or method not in {"GET", "POST"}:
        raise ValueError(f"request is outside the weekly invoice API allowlist: {method} {path}")
    if method == "GET" and payload is not None:
        raise ValueError("GET requests must not have a payload")
    if method == "POST" and payload is None:
        raise ValueError("POST requests require a JSON payload")

    headers = {"Accept": "application/json"}
    body = None
    if payload is not None:
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        headers["Content-Type"] = "application/json"
        headers["Content-Length"] = str(len(body))

    log.info("PHASE invoice_api_request method=%s path=%s", method, path)
    conn = http.client.HTTPConnection("127.0.0.1", 18182, timeout=15)
    try:
        conn.request(method, path, body=body, headers=headers)
        response = conn.getresponse()
        response_body = response.read()
        result: dict[str, object] = {
            "status": int(response.status),
            "reason": str(response.reason),
            "body_b64": base64.b64encode(response_body).decode("ascii"),
        }
        if 200 <= response.status < 300:
            log.info("PHASE invoice_api_response method=%s path=%s status=%s", method, path, response.status)
        else:
            log.error("SOFT_FAIL invoice_api_response method=%s path=%s status=%s reason=%s", method, path, response.status, response.reason)
        return result
    except Exception:
        log.exception("SOFT_FAIL invoice_api_uncertain_outcome method=%s path=%s", method, path)
        raise
    finally:
        conn.close()
